const icon=name=>`<svg class="icon" aria-hidden="true" focusable="false"><use href="icons.svg#${name}"></use></svg>`;
const $=s=>document.querySelector(s);
const coachAssetImages=['assets/chick-emotions.webp','assets/chick-positive-emotions.webp'].map(src=>{const image=new Image();image.src=src;return image});
const coachAssetsReady=Promise.allSettled(coachAssetImages.map(image=>image.decode()));
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function read(key,fallback){try{return JSON.parse(localStorage.getItem(key))||fallback}catch{return fallback}}
let notes=read('muguang-notes',[]);if(!Array.isArray(notes))notes=[];
let progress=read('refinetaste-course-v2',{});if(typeof progress!=='object'||Array.isArray(progress))progress={};
let course=null,current=0,chapter=0,selected=null,sessionAnswers={},screen='map',reviewController=null,reviewGeneration=0;
function persist(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true}catch{return false}}
function updateCount(){for(const id of ['note-count','note-count-in']){const counter=$('#'+id);if(window.RefineText)window.RefineText.slots(counter,notes.length);else counter.textContent=notes.length;}for(const id of ['notes-open','notebook-in'])$('#'+id).setAttribute('aria-label',`我的笔记，${notes.length} 条收藏`)}updateCount();
function checkpoint(){return progress[current]||{}}
function saveProgress(patch){progress[current]={...checkpoint(),...patch};syncBookmark();const ok=persist('refinetaste-course-v2',progress);if(!ok&&$('#draft-storage'))$('#draft-storage').textContent='浏览器无法保存，离开前请复制内容';return ok}
function focusTitle(){$('#training').scrollTop=0;$('#exercise-title')?.focus({preventScroll:true})}
function stopReview(){reviewGeneration++;reviewController?.abort();reviewController=null;hideTyping()}
function transition(update){stopReview();window.RefineParticles?.dispose();return window.RefineMotion.swap($('#exercise'),()=>{update();focusTitle()})}
function setExerciseProgress(value=null){const bar=$('#exercise-progress');bar.hidden=value===null;if(value===null)return;bar.setAttribute('aria-valuenow',value);bar.firstElementChild.style.transform=`scaleX(${value/8})`}
function chapterArt(index){return `<canvas class="chapter-illustration" data-particle-chapter="${index}" width="352" height="300" aria-hidden="true"></canvas>`}
function bindCatalogs(){document.querySelectorAll('.chapter-catalog').forEach(wrapper=>{const button=wrapper.querySelector('button'),popup=wrapper.querySelector('.catalog-popup');let timer;const hide=()=>{clearTimeout(timer);popup.hidden=true;button.setAttribute('aria-expanded','false')};const show=()=>{clearTimeout(timer);popup.hidden=false;button.setAttribute('aria-expanded','true');const rect=button.getBoundingClientRect(),height=popup.getBoundingClientRect().height;popup.style.left=Math.max(16,Math.min(rect.left,innerWidth-popup.offsetWidth-16))+'px';popup.style.top=Math.max(16,rect.bottom+10+height<innerHeight-16?rect.bottom+10:rect.top-height-10)+'px'};wrapper.onpointerenter=show;wrapper.onpointerleave=event=>{if(event.pointerType!=='touch')timer=setTimeout(hide,140)};popup.onpointerenter=()=>clearTimeout(timer);popup.onpointerleave=event=>{if(event.pointerType!=='touch')timer=setTimeout(hide,140)};button.onfocus=show;wrapper.onfocusout=event=>{if(!wrapper.contains(event.relatedTarget))hide()};button.onclick=show;wrapper.onkeydown=event=>{if(event.key==='Escape'){event.preventDefault();event.stopPropagation();hide()}}})}
async function showMap(){
 stopReview();stopCoachMood();screen='map';$('#coach-header').hidden=true;$('#exit').innerHTML=icon('arrow-left');$('#exit').setAttribute('aria-label','返回首页');setExerciseProgress();
 if(!course){$('#exercise').innerHTML='<div class="course-loading" role="status">正在打开课程…</div>';try{const r=await fetch('course.json');if(!r.ok)throw Error();course=await r.json()}catch{$('#exercise').innerHTML='<div class="empty"><h2 id="exercise-title">课程暂时没有打开</h2><p>请检查网络，再试一次。</p><button id="course-retry" class="primary">重新加载</button></div>';$('#course-retry').onclick=showMap;return}}
 await coachAssetsReady;
 $('#exercise').innerHTML=`<div class="course-map"><h2 id="exercise-title" class="sr-only" tabindex="-1">课程目录</h2><div class="course-chapters">${course.chapters.map((ch,i)=>{const qs=course.questions.filter(q=>q.chapter===i),done=qs.filter(q=>progress[q.id]?.done).length;return `<article class="course-chapter"><button class="chapter-entry" data-chapter="${i}" aria-label="${done?'重新练习':'开始练习'}${esc(ch.title)}"></button>${chapterArt(i)}<div class="chapter-copy"><h3>${['一','二','三'][i]}、${ch.title}</h3><p>${ch.subtitle}</p><div class="chapter-catalog"><button class="catalog-trigger chapter-progress" aria-label="${esc(ch.title)}，已完成 ${done} / 8，查看知识点" aria-expanded="false" aria-controls="catalog-${i}"><span class="chapter-progress-track"><span data-chapter-progress="${done/8}"></span></span></button><div id="catalog-${i}" class="catalog-popup" role="region" aria-label="${ch.title}知识点目录" hidden><ol>${qs.map(q=>`<li class="catalog-point" data-complete="${!!progress[q.id]?.done}"><strong>${esc(q.principle)}</strong></li>`).join('')}</ol></div></div></div><div class="chapter-action" aria-hidden="true"><span class="chapter-arrow">${icon('arrow-right')}</span></div></article>`}).join('')}</div></div>`;
 document.querySelectorAll('[data-chapter]').forEach(b=>b.onclick=()=>transition(()=>begin(+b.dataset.chapter)));document.querySelectorAll('[data-chapter-progress]').forEach(fill=>fill.style.transform=`scaleX(${fill.dataset.chapterProgress})`);bindCatalogs();window.RefineParticles.mount($('#exercise'));focusTitle();
}
function begin(index){chapter=index;current=index*8;selected=null;sessionAnswers={};screen='lesson';window.RefineMetrics?.start(current);render()}
document.querySelectorAll('[data-start]').forEach(b=>b.onclick=()=>{$('#training').showModal();showMap()});
$('#exit').onclick=()=>{if(screen==='map'){stopReview();window.RefineMotion.closeDialog($('#training'))}else transition(showMap)};
$('#training').addEventListener('close',stopReview);
function sources(q){return q.sources?.length?`<div class="case-source">参考阅读：${q.sources.map(s=>`<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)} ${icon('arrow-up-right')}</a>`).join('')}<span>练习画面为原创示意，并非原站截图或原作复刻。</span></div>`:''}
function specimen(v){
 const cls=esc(v.kind),lines=v.lines.map(esc);
 let content=lines.map(t=>`<p>${t}</p>`).join('');
 if(v.kind.startsWith('menu'))content=lines.map(t=>`<div class="menu-row">${t.split('｜').map((x,i)=>`<span class="menu-part-${i}">${x}</span>`).join('')}</div>`).join('');
 if(v.kind.startsWith('status'))content=lines.map(t=>{const [name,status]=t.split('｜');return `<p class="status-row"><span>${name}</span><span class="status-marker ${status.includes('失败')||status==='红'?'failed':''}">${v.kind.includes('color-only')?'●':status}</span></p>`}).join('');
 if(v.kind.startsWith('chart'))content=`<div class="mini-chart ${v.kind.includes('truncated')?'axis-cut':''}"><div class="bar bar-a"><span>82</span></div><div class="bar bar-b"><span>84</span></div></div><div class="chart-key">活动 A　/　活动 B</div><p>${lines[2]}</p>`;
 return `<div class="specimen ${cls}"><div class="specimen-tag">${esc(v.tag)}</div><strong class="specimen-title">${esc(v.title)}</strong><div class="specimen-content">${content}</div></div>`
}
function render(){
 screen='lesson';const q=course.questions[current],ch=course.chapters[chapter];selected=sessionAnswers[current]??null;
 $('#coach-header').hidden=false;setCoachMood('curious');$('#exit').innerHTML=icon('arrow-left');$('#exit').setAttribute('aria-label','返回课程目录');setExerciseProgress(current%8+1);
 $('#exercise').innerHTML=`<div class="lesson-stream"><section class="exercise-heading question-heading chat-message assistant" aria-label="JOJO 的提问"><div class="chat-bubble question-bubble"><h2 id="exercise-title" tabindex="-1">${esc(q.title)}</h2><p>${esc(q.brief)}</p>${q.kind==='open'?`<p class="question-task">${esc(q.prompt)}</p>`:''}</div></section>${q.kind==='choice'?`<div class="options" aria-label="JOJO 发来的两个设计方案">${q.labels.map((label,i)=>`<button class="option" data-option="${i}" aria-label="选项 ${i?'B':'A'}：${esc(label)}"><div class="option-design">${q.visuals?.length?specimen(q.visuals[i]):sample(q,i)}</div><div class="option-label"><span class="letter">${i?'B':'A'}</span></div></button>`).join('')}</div>`:`<div class="open-case ${q.visuals.length>1?'case-pair':''}" aria-label="JOJO 发来的设计案例">${q.visuals.map(specimen).join('')}</div>`}<span id="bookmark-status" class="sr-only" role="status"></span><div id="feedback-slot" aria-live="polite"></div></div>`;
 const heading=$('#exercise .question-heading'),designReady=window.RefineMotion.assembleDesign($('#exercise .options')||$('#exercise .open-case'),heading);
 if(q.kind==='choice')document.querySelectorAll('[data-option]').forEach(b=>b.onclick=()=>answer(+b.dataset.option));else Promise.resolve(designReady).then(()=>{if(heading.isConnected)renderOpen(q)});focusTitle();
}
function recordAnswer(choice){if(Object.hasOwn(sessionAnswers,current))return;sessionAnswers[current]=choice;window.RefineMetrics?.send('answer',{q:current,choice});saveProgress({done:true,choice})}
function nextButton(){return `<button id="bookmark" class="bookmark" aria-label="收藏这道题" aria-pressed="false"><svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M6 3h12v18l-6-4-6 4Z"/></svg></button><button class="primary" id="next" aria-keyshortcuts="n" title="下一步">${current%8===7?'查看本阶回顾':'下一题'}<span>${icon('arrow-right')}</span></button>`}
function bindNext(){$('#bookmark').onclick=toggleBookmark;updateBookmark();$('#next').onclick=()=>transition(()=>{if(course.questions[current].kind==='open'&&checkpoint().messages?.some(message=>message.role==='user'))recordAnswer(-1);if(current%8===7)result();else{current++;selected=null;render()}})}
function answer(i){
 if(selected!==null)return;window.RefineMotion.finishDesignBuild($('.options'));selected=i;recordAnswer(i);const q=course.questions[current];$('.options').classList.add('answered');
 document.querySelectorAll('[data-option]').forEach(b=>{b.disabled=true;b.classList.toggle('selected',+b.dataset.option===i);b.classList.toggle('correct',+b.dataset.option===q.correct)});
 const verdict=document.createElement('span');verdict.className=`option-verdict ${i===q.correct?'is-correct':'is-incorrect'}`;verdict.setAttribute('role','img');verdict.setAttribute('aria-label',i===q.correct?'答对了':'答错了');verdict.innerHTML=icon(i===q.correct?'check':'xmark');document.querySelector(`[data-option="${i}"] .option-label`).append(verdict);
 $('#feedback-slot').innerHTML=`<div class="lesson-next">${nextButton()}</div><div id="discussion" hidden></div>`;
 const restored=checkpoint().messages?.some(message=>message.role==='user');if(!restored)$('#feedback-slot').classList.add('feedback-sequence');openDiscussion(!restored,restored);bindNext();

}
function renderOpen(q){
 const saved=checkpoint();
 // Bring old submitted writing and its review into the same conversation.
 if(!saved.messages?.some(message=>message.role==='user')&&saved.done&&saved.draft){const messages=[...coachOpening(q),{role:'user',content:saved.draft}];if(saved.feedback)messages.push({role:'assistant',content:[...saved.feedback.strengths,...saved.feedback.gaps,saved.feedback.suggestion,saved.feedback.question].join('\n')});saveProgress({messages,openingVersion:4})}
 else if(!saved.chatDraft&&saved.draft&&!saved.done)saveProgress({chatDraft:saved.draft});
 const restored=checkpoint().messages?.some(message=>message.role==='user');
 $('#feedback-slot').innerHTML=`<div id="open-next" class="lesson-next" ${restored?'':'hidden'}>${nextButton()}</div><div id="discussion" hidden></div>`;
 openDiscussion(false,restored);bindNext();
}
function result(){stopCoachMood();screen='result';$('#coach-header').hidden=true;window.RefineMetrics?.send('complete');const qs=course.questions.slice(chapter*8,chapter*8+8),choices=qs.filter(q=>q.kind==='choice'),correct=choices.filter(q=>sessionAnswers[q.id]===q.correct).length,opens=qs.filter(q=>q.kind==='open'),review=choices.filter(q=>sessionAnswers[q.id]!==q.correct);setExerciseProgress(8);$('#exercise').innerHTML=`<div class="result"><span class="section-kicker">${course.chapters[chapter].level} · ${course.chapters[chapter].title}</span><h2 id="exercise-title" tabindex="-1">让每个判断，<br>多一点自己的依据。</h2><div class="result-count">${correct}<small> / ${choices.length} 个比较判断</small></div><p>你还完成了 ${opens.length} 次开放表达。<br>开放题不判对错；比较题也只是本次情境下的判断，不是审美能力评分。</p>${review.length?`<p>值得再观察：${review.map(q=>esc(q.principle)).join('、')}。</p>`:''}<p>${esc(course.chapters[chapter].objective)}</p><div class="result-actions">${chapter<2?`<button class="primary" id="next-chapter">进入${course.chapters[chapter+1].level} ${icon('arrow-right')}</button>`:''}<button class="secondary" id="result-map">回到课程目录</button><button class="secondary" id="result-notes">查看我的笔记</button></div></div>`;if($('#next-chapter'))$('#next-chapter').onclick=()=>transition(()=>begin(chapter+1));$('#result-map').onclick=()=>transition(showMap);$('#result-notes').onclick=openNotes;focusTitle()}
function sample(q,i){if(q.type==='card')return `<div class="sample-card ${i===q.correct?'good':q.bad}"><div class="studio">LINJIAN DESIGN STUDIO</div><div><div class="name">陈默</div><div class="position">品牌设计师</div></div><div class="contact">hello@linjian.studio<br>138 0000 2026</div></div>`;if(q.type==='resource'||q.type==='offer'){const good=i===q.correct;const offer=q.type==='offer';return `<div class="resource-demo"><div class="app-bar"><b>生活灵感</b><span>附近　收藏</span></div><div class="resource-banner ${good?'':'loud'}"><strong>${offer?(good?'新客，来杯好咖啡。':'免费喝咖啡！'):(good?'周末，走慢一点。':'周末必去！立即出发！')}</strong><p>${offer?(good?'领 10 元咖啡券 · 满 30 元可用':'超值福利！限时抢！'):(good?'发现附近的 3 条散步路线':'发现宝藏路线！错过再等一年！')}</p><span>${offer?'去领券':'探索散步路线'} ${icon('arrow-right')}</span></div><div class="app-placeholder"><i></i><i></i><i></i></div></div>`}if(q.type==='path')return `<div class="path-sample"><div><small>用户看见</small>附近免费展览 ${icon('arrow-right')}</div><span>${icon('arrow-down')}</span><div><small>点击后抵达</small>${i===1?'附近免费展览列表 · 默认按距离排序':'品牌首页 · 商城 / 动态 / 会员 / 更多'}</div></div>`;return `<div class="path-sample"><div><small>给设计同事的反馈</small>${esc(q.labels[i])}</div><div><small>下一步</small>${i===1?'选出主利益，调整字号，再放回页面检验。':'设计师需要继续追问：「具体指哪里？」'}</div></div>`}
function noteForQuestion(){return notes.find(n=>n.questionId===current)}
function syncBookmark(){const note=noteForQuestion();if(!note)return;Object.assign(note,{draft:checkpoint().draft||'',feedback:checkpoint().feedback||null,messages:checkpoint().messages||[]});persist('muguang-notes',notes)}
function updateBookmark(){const b=$('#bookmark');if(!b)return;const saved=!!noteForQuestion();b.setAttribute('aria-pressed',saved);b.setAttribute('aria-label',saved?'取消收藏':'收藏这道题');b.title=saved?'已收藏，点击取消':'收藏到我的笔记'}
function toggleBookmark(event){const existing=noteForQuestion(),previous=notes.slice();if(existing)notes=notes.filter(n=>n!==existing);else{const q=course.questions[current];notes.push({questionId:current,title:q.title,topic:q.principle,brief:q.brief,date:new Date().toLocaleDateString('zh-CN'),draft:checkpoint().draft||'',feedback:checkpoint().feedback||null,messages:checkpoint().messages||[]})}if(!persist('muguang-notes',notes)){notes=previous;$('#bookmark-status').textContent='浏览器无法保存，请先复制需要保留的内容。';return}updateBookmark();updateCount();$('#bookmark-status').textContent=existing?'已取消收藏':'已收藏到我的笔记';if(!existing)window.RefineMetrics?.send('note_saved');if(event.detail!==0)window.RefineMotion.bookmarkFeedback($('#bookmark .icon'),$('#note-count-in'))}
const coachEmotions=['neutral','happy','thinking','curious','surprised','encouraging','empathetic','confused','playful','delighted','approving','inspired','relieved','grateful','amused'];
function conversationMarkup(messages){return messages.map(m=>`<div class="chat-message ${m.role}"><div class="chat-bubble"><p>${esc(m.content)}</p></div></div>`).join('')}
let coachMoodTimer=null,coachMoodAnchor='curious',coachMoodCurrent='curious';
const coachMoodFamilies=[['neutral','curious','thinking'],['happy','delighted','approving','inspired','encouraging','grateful','amused','playful'],['empathetic','relieved'],['confused','thinking','curious'],['surprised','curious','inspired']];
function stopCoachMood(){clearTimeout(coachMoodTimer);coachMoodTimer=null}
function drawCoachMood(mood){const avatar=$('#coach-avatar .coach-avatar');if(!avatar)return;coachMoodCurrent=mood;avatar.className=`coach-avatar coach-emotion${coachEmotions.indexOf(mood)>=9?' positive-emotion':''} emotion-${mood}`}
function scheduleCoachMood(){stopCoachMood();if(screen!=='lesson'||!$('#training').open||document.hidden||matchMedia('(prefers-reduced-motion: reduce)').matches)return;coachMoodTimer=setTimeout(()=>{const family=coachMoodFamilies.find(group=>group.includes(coachMoodAnchor))||coachMoodFamilies[0],alternatives=family.filter(mood=>mood!==coachMoodCurrent);drawCoachMood(alternatives[Math.floor(Math.random()*alternatives.length)]);scheduleCoachMood()},7000+Math.random()*1000)}
function setCoachMood(emotion='neutral'){coachMoodAnchor=coachEmotions.includes(emotion)?emotion:'neutral';drawCoachMood(coachMoodAnchor);scheduleCoachMood()}
document.addEventListener('visibilitychange',()=>{if(document.hidden)stopCoachMood();else scheduleCoachMood()});
matchMedia('(prefers-reduced-motion: reduce)').addEventListener('change',scheduleCoachMood);


function animateMessage(element){element=element?.querySelector('.chat-bubble')||element;if(!element||matchMedia('(prefers-reduced-motion: reduce)').matches)return;element.animate([{opacity:0,transform:'translateY(9px) scale(.98)'},{opacity:1,transform:'translateY(0) scale(1)'}],{duration:240,easing:'cubic-bezier(.23,1,.32,1)'})}

function coachOpening(q){return (q.kind==='open'?q.coachOpening.slice(0,1):q.coachOpening).map(content=>({role:'assistant',content,emotion:'curious'}))}
function appendChat(message){const list=$('#chat-messages');list.insertAdjacentHTML('beforeend',conversationMarkup([message]));animateMessage(list.lastElementChild);window.RefineText?.text(list.lastElementChild.querySelector('p'));if(message.role==='assistant')setCoachMood(message.emotion)}
function updateSend(){const button=$('#chat-send'),input=$('#chat-input');if(!button||!input)return;button.disabled=!!reviewController||!input.value.trim();const measure=document.createElement('canvas').getContext('2d');measure.font=getComputedStyle(input).font;input.closest('.chat-composer').style.setProperty('--composer-content',Math.ceil(measure.measureText(input.value).width+90)+'px')}
function openDiscussion(sequenced=false,instant=false){const box=$('#discussion');if(!box.hidden){$('#chat-input').focus();return}box.hidden=false;let messages=checkpoint().messages||[];const fresh=!messages.length;if(fresh||checkpoint().openingVersion!==4){const opening=coachOpening(course.questions[current]);let priorOpening=0;while(priorOpening<2&&messages[priorOpening]?.role==='assistant')priorOpening++;messages=[...opening,...messages.slice(priorOpening)];saveProgress({messages,openingVersion:4})}box.innerHTML=`<section class="discussion" aria-label="和 JOJO 聊聊"><div id="chat-messages" aria-live="polite"></div><form id="chat-form"><div class="chat-composer"><label for="chat-input" class="sr-only">给 JOJO 发消息</label><input id="chat-input" type="text" maxlength="2000" required autocomplete="off" placeholder="说说你的想法…"><button type="submit" id="chat-send" aria-label="发送消息" title="发送 · Enter" disabled>${icon('arrow-up')}</button></div><p id="chat-status" role="status"></p></form></section>`;$('#chat-messages').innerHTML=conversationMarkup(checkpoint().messages||[]);setCoachMood((checkpoint().messages||[]).findLast(message=>message.role==='assistant')?.emotion);if(fresh&&!sequenced&&!instant)animateMessage($('#chat-messages').lastElementChild);if(window.RefineText&&!instant){let delay=sequenced?450:0;const bubbles=[...$('#chat-messages').children];for(const [index,bubble] of bubbles.entries()){if(index>1)break;const paragraph=bubble.querySelector('p');if(sequenced)bubble.querySelector('.chat-bubble').style.animationDelay=delay+'ms';window.RefineText.text(paragraph,{delay});if(sequenced)delay+=window.RefineText.duration(paragraph.textContent)+160;}if(sequenced)$('#chat-form').style.animationDelay=delay+'ms';}$('#chat-input').value=checkpoint().chatDraft||'';$('#chat-input').oninput=()=>{saveProgress({chatDraft:$('#chat-input').value});updateSend()};$('#chat-input').addEventListener('keydown',event=>{if(event.key==='Enter'&&(event.isComposing||event.keyCode===229))event.preventDefault()});$('#chat-form').onsubmit=sendChat;updateSend();if(sequenced&&!matchMedia('(prefers-reduced-motion: reduce)').matches){const form=$('#chat-form');form.inert=true;form.addEventListener('animationend',event=>{if(event.target===form)form.inert=false},{once:true})}}
async function sendChat(event){event.preventDefault();if(reviewController)return;const text=$('#chat-input').value.trim();if(!text)return;const message={role:'user',content:text},messages=[...(checkpoint().messages||[]),message];saveProgress({messages,chatDraft:''});if(course.questions[current].kind==='open'){recordAnswer(-1);$('#open-next').hidden=false;}$('#chat-input').value='';updateSend();appendChat(message);$('#chat-input').focus();await requestChat()}
function hideTyping(){$('#coach-typing')?.remove()}
function showTyping(){hideTyping();$('#chat-messages').insertAdjacentHTML('beforeend','<div id="coach-typing" class="chat-message assistant typing-message" role="status" aria-label="JOJO 正在回复"><div class="chat-bubble"><span class="typing-dots" aria-hidden="true"><i></i><i></i><i></i></span></div></div>');animateMessage($('#coach-typing'))}
async function requestChat(){if(reviewController)return;const messages=checkpoint().messages||[];if(messages.at(-1)?.role!=='user')return;const generation=++reviewGeneration,questionId=current,controller=new AbortController();reviewController=controller;const timer=setTimeout(()=>controller.abort(),48000);$('#chat-send').disabled=true;$('#chat-status').textContent='';showTyping();try{const response=await fetch('api/review',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:crypto.randomUUID(),q:questionId,mode:'chat',messages:messages.slice(-12),answer:messages.at(-1).content}),signal:controller.signal});const data=await response.json();if(generation!==reviewGeneration)return;if(!response.ok)throw Error(data.error||'暂时无法回复，请重试。');hideTyping();saveProgress({messages:[...messages,{role:'assistant',content:data.reply,emotion:coachEmotions.includes(data.emotion)?data.emotion:'neutral'}]});appendChat({role:'assistant',content:data.reply,emotion:coachEmotions.includes(data.emotion)?data.emotion:'neutral'});$('#chat-status').textContent=''}catch(error){if(generation!==reviewGeneration)return;hideTyping();$('#chat-status').textContent=(error.name==='AbortError'?'等待较久，请重试。':error.message)+' 你的消息已保留。';const retry=document.createElement('button');retry.type='button';retry.className='chat-invite';retry.textContent='重试';retry.onclick=requestChat;$('#chat-status').append(retry)}finally{clearTimeout(timer);if(generation===reviewGeneration){hideTyping();reviewController=null;updateSend()}}}
function noteBody(n){return `${n.brief?`<p>${esc(n.brief)}</p>`:''}${n.text?`<p>${esc(n.text)}</p>`:''}${n.draft?`<p>${esc(n.draft)}</p>`:''}${n.feedback?`<p>${esc([...n.feedback.strengths,...n.feedback.gaps,n.feedback.suggestion,n.feedback.question].join('\n'))}</p>`:''}${conversationMarkup(n.messages||[])}`}
let notesOpener=null,notesDetail=null,notesScroll=0;
function noteTitle(note){return note.topic&&note.title?`${note.topic}：${note.title}`:note.title||note.topic||'设计笔记'}
function renderNotesIndex(returnIndex=null){notesDetail=null;$('#notebook-title').textContent='我的笔记';$('#notes-description').textContent=notes.length?`${notes.length} 条收藏 · 保存在当前浏览器`:'收藏的题目和对话，保存在当前浏览器中。';$('#notes-list').innerHTML=notes.length?`<ol class="notes-index">${notes.map((n,index)=>({n,index})).reverse().map(({n,index})=>`<li><button class="note-index-row" data-note="${index}"><span class="note-index-copy"><strong>${esc(noteTitle(n))}</strong><small>${esc(n.date)}${n.messages?.length?` · ${n.messages.length} 条消息`:''}</small></span>${icon('nav-arrow-right')}</button></li>`).join('')}</ol>`:'<div class="empty">还没有收藏。<br>作答后点击「下一题」旁的书签，把题目和对话留在这里。</div>';document.querySelectorAll('[data-note]').forEach(button=>button.onclick=()=>{notesScroll=$('#notebook').scrollTop;renderNoteDetail(+button.dataset.note)});if(returnIndex!==null){$('#notebook').scrollTop=notesScroll;document.querySelector(`[data-note="${returnIndex}"]`)?.focus({preventScroll:true})}}
function renderNoteDetail(index){const note=notes[index];if(!note){renderNotesIndex();return}notesDetail=index;$('#notebook-title').textContent=noteTitle(note);$('#notes-description').textContent=note.date;$('#notes-list').innerHTML=`<button class="notes-back text-link">${icon('arrow-left')} 返回列表</button><article class="note-item note-detail">${noteBody(note)}</article>`;$('.notes-back').onclick=()=>renderNotesIndex(index);$('#notebook').scrollTop=0;$('#notebook-title').focus({preventScroll:true})}
function positionNotes(){if($('#notebook').hidden)return;const anchor=$('#training').open?$('#notebook-in'):$('#notes-open'),rect=anchor.getBoundingClientRect();const top=Math.min(Math.max(rect.bottom+14,70),innerHeight-180);$('#notebook').style.setProperty('--notes-top',top+'px');$('#notebook').style.setProperty('--notes-right',Math.max(16,innerWidth-rect.right)+'px')}
function closeNotes(restoreFocus=true){$('#notebook').hidden=true;document.body.classList.remove('notes-visible');for(const id of ['notes-open','notebook-in'])$('#'+id).setAttribute('aria-expanded','false');if(restoreFocus&&notesOpener?.isConnected)notesOpener.focus({preventScroll:true})}
function openNotes(event){const button=event?.currentTarget;if(!$('#notebook').hidden&&button?.matches('#notes-open,#notebook-in')){closeNotes();return}syncBookmark();notesOpener=$('#training').open?$('#notebook-in'):$('#notes-open');($('#training').open?$('#training'):document.body).append($('#notebook'));renderNotesIndex();$('#notebook').hidden=false;document.body.classList.add('notes-visible');for(const id of ['notes-open','notebook-in']){$('#'+id).setAttribute('aria-controls','notebook');$('#'+id).setAttribute('aria-expanded','true')}positionNotes();$('#notebook').scrollTop=0;$('#notebook-title').focus({preventScroll:true});if(!matchMedia('(prefers-reduced-motion: reduce)').matches)$('#notebook').animate([{opacity:0,transform:'translateY(-6px)'},{opacity:1,transform:'translateY(0)'}],{duration:200,easing:'cubic-bezier(.23,1,.32,1)'})}
$('#notes-open').onclick=openNotes;$('#notebook-in').onclick=openNotes;$('#notes-close').onclick=()=>closeNotes();
$('#training').addEventListener('close',()=>{stopCoachMood();window.RefineParticles?.dispose();closeNotes(false)});window.addEventListener('resize',positionNotes);
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!$('#notebook').hidden){event.preventDefault();event.stopImmediatePropagation();closeNotes()}},true);

document.addEventListener('keydown',event=>{
 if(event.defaultPrevented||event.repeat||event.isComposing||event.keyCode===229||event.ctrlKey||event.metaKey||event.altKey||event.key.toLowerCase()!=='n')return;
 if(event.target.closest('input,textarea,select,[contenteditable]:not([contenteditable="false"]),[role="textbox"]'))return;
 if(screen!=='lesson'||!$('#training').open||event.target.closest('#notebook')||$('#exercise').hasAttribute('aria-busy'))return;
 const next=$('#next');if(!next||next.disabled||!next.getClientRects().length)return;
 event.preventDefault();next.click();
});

document.addEventListener('pointermove',event=>{
 if(!event.movementX&&!event.movementY)return;
 const option=event.target.closest('.option');
 if(option&&!option.parentElement.hasAttribute('data-design-entering'))option.classList.add('hover-ready');
});
document.addEventListener('pointerout',event=>{
 const option=event.target.closest('.option');
 if(option&&!option.contains(event.relatedTarget))option.classList.remove('hover-ready');
});

document.addEventListener('pointerdown',event=>{document.querySelectorAll('.chapter-catalog').forEach(wrapper=>{if(!wrapper.contains(event.target)){wrapper.querySelector('.catalog-popup').hidden=true;wrapper.querySelector('button').setAttribute('aria-expanded','false')}})});
